-- Run in Supabase SQL Editor once. Enable email OTP in Authentication.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null check (char_length(display_name) between 1 and 60));
create table if not exists public.shared_lists (id uuid primary key default gen_random_uuid(), title text not null check (char_length(title) between 1 and 100), owner_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.shared_members (list_id uuid not null references public.shared_lists(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, joined_at timestamptz not null default now(), primary key(list_id,user_id));
create table if not exists public.shared_items (id uuid primary key default gen_random_uuid(), list_id uuid not null references public.shared_lists(id) on delete cascade, text text not null check (char_length(text) between 1 and 180), person text default '', done boolean not null default false, created_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.shared_invites (token uuid primary key default gen_random_uuid(), list_id uuid not null references public.shared_lists(id) on delete cascade, created_by uuid not null references auth.users(id), created_at timestamptz default now(), expires_at timestamptz not null default (now()+interval '14 days'));
create index if not exists shared_items_list_idx on public.shared_items(list_id);
create index if not exists shared_members_user_idx on public.shared_members(user_id);
create or replace function public.is_member(p_list uuid) returns boolean language sql stable security definer set search_path = '' as $$select exists(select 1 from public.shared_members where list_id=p_list and user_id=(select auth.uid()))$$;
revoke all on function public.is_member(uuid) from public; grant execute on function public.is_member(uuid) to authenticated;
create or replace function public.add_owner_member() returns trigger language plpgsql security definer set search_path = '' as $$begin insert into public.shared_members(list_id,user_id) values(new.id,new.owner_id);return new;end$$;
drop trigger if exists list_owner_join on public.shared_lists;
create trigger list_owner_join after insert on public.shared_lists for each row execute function public.add_owner_member();
alter table public.profiles enable row level security;
alter table public.shared_lists enable row level security;
alter table public.shared_members enable row level security;
alter table public.shared_items enable row level security;
alter table public.shared_invites enable row level security;
drop policy if exists profile_self_select on public.profiles;
create policy profile_self_select on public.profiles for select to authenticated using(id=(select auth.uid()));
drop policy if exists profile_self_insert on public.profiles;
create policy profile_self_insert on public.profiles for insert to authenticated with check(id=(select auth.uid()));
drop policy if exists profile_self_update on public.profiles;
create policy profile_self_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
drop policy if exists lists_read on public.shared_lists;
create policy lists_read on public.shared_lists for select to authenticated using(public.is_member(id));
drop policy if exists lists_create on public.shared_lists;
create policy lists_create on public.shared_lists for insert to authenticated with check(owner_id=(select auth.uid()));
drop policy if exists lists_update on public.shared_lists;
create policy lists_update on public.shared_lists for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
drop policy if exists lists_delete on public.shared_lists;
create policy lists_delete on public.shared_lists for delete to authenticated using(owner_id=(select auth.uid()));
drop policy if exists members_read on public.shared_members;
create policy members_read on public.shared_members for select to authenticated using(public.is_member(list_id));
drop policy if exists members_leave on public.shared_members;
create policy members_leave on public.shared_members for delete to authenticated using(user_id=(select auth.uid()) and not exists(select 1 from public.shared_lists where id=list_id and owner_id=(select auth.uid())));
drop policy if exists items_read on public.shared_items;
create policy items_read on public.shared_items for select to authenticated using(public.is_member(list_id));
drop policy if exists items_insert on public.shared_items;
create policy items_insert on public.shared_items for insert to authenticated with check(public.is_member(list_id) and created_by=(select auth.uid()));
drop policy if exists items_update on public.shared_items;
create policy items_update on public.shared_items for update to authenticated using(public.is_member(list_id)) with check(public.is_member(list_id));
drop policy if exists items_delete on public.shared_items;
create policy items_delete on public.shared_items for delete to authenticated using(public.is_member(list_id));
-- No direct read/write policies for invitations. Only guarded RPCs expose tokens.
create or replace function public.create_share_link(p_list_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$declare t uuid;begin if (select auth.uid()) is null or not public.is_member(p_list_id) then raise exception 'Not a member';end if;insert into public.shared_invites(list_id,created_by) values(p_list_id,(select auth.uid())) returning token into t;return t;end$$;
create or replace function public.join_shared_list(p_token uuid) returns uuid language plpgsql security definer set search_path = '' as $$declare l uuid;begin if (select auth.uid()) is null then raise exception 'Sign in first';end if;select list_id into l from public.shared_invites where token=p_token and expires_at>now();if l is null then raise exception 'Invitation expired or invalid';end if;insert into public.shared_members(list_id,user_id) values(l,(select auth.uid())) on conflict do nothing;return l;end$$;
create or replace function public.list_member_names(p_list_id uuid) returns text[] language sql stable security definer set search_path = '' as $$ select coalesce(array_agg(coalesce(nullif(trim(p.display_name),''),'Member') order by m.joined_at),array[]::text[]) from public.shared_members m left join public.profiles p on p.id=m.user_id where m.list_id=p_list_id and public.is_member(p_list_id) $$;
revoke all on function public.create_share_link(uuid),public.join_shared_list(uuid),public.list_member_names(uuid) from public;
grant execute on function public.create_share_link(uuid),public.join_shared_list(uuid),public.list_member_names(uuid) to authenticated;
-- Supabase Dashboard: Database > Publications > supabase_realtime > enable shared_items.
